// DM mission files: Street Commissions, part 1 (intro, Chainring, Dead Air, Lea Boys, Velvet Circuit, Towpath Union).
// The paint roll itself is always Graft, rolled from Tag Studio (Alt+G); the checks here are the ones the GM calls around it.
// Quality tiers: Proper Mess, Bad Luck, Just About, Sorted, Smashed It, Legendary.
export default {
  'tg-intro-01': {
    brief: `The tagging tutorial. Auntie Pat lends the crew a can and points out a wall she's happy for them to paint: the Morning Lane workshop wall, next to her own shop. It's legal, sanctioned and zero Heat. The job teaches targeting, the Graft roll, the six quality tiers and the Banana Watch. The twist: even a Proper Mess stays visible on the wall; it just earns no job credit until it's repainted properly.`,
    openTitle: `Read aloud: first can`,
    open: `Pat holds out a can of spray paint like it's a glass of sherry. "My wall, darlings. My rules. Nobody's calling the Old Bill on my own wall." She points at the brick beside the shutter, where an old faded advert for bicycle tyres is peeling off. "Put your name on it. Make it nice." She shakes the can for you, rattle rattle. "And if it's horrible, we'll paint over it and pretend it never happened."`,
    cast: ['auntie-pat', 'spanner-rob'],
    roles: {'auntie-pat': `Lends the can and the wall. Delighted to watch.`, 'spanner-rob': `Comments from the workshop door. Has opinions about lettering.`},
    scenes: [
      {at: 'SP-HC-MORNING-WALL', title: `The Morning Lane workshop wall`, read: `Morning Lane in the afternoon. Trains rattle over the arches. Pat's wall is old London brick, softened by a hundred years of soot, with a ghost of a tyre advert still showing through. Spanner Rob leans in the workshop doorway with his tea. "Big letters," he says. "Nobody reads small letters."`,
        text: `Open Tag Studio (Alt+G), pick the wall, and roll Graft. The quality tier shows on the wall straight away: Proper Mess and Bad Luck stay visible but don't count; Just About or better completes the job. The time spent goes on the Banana Watch. This wall is sanctioned, so no Heat.`,
        checks: [['aim', 'easy', `Get the first can's nozzle angle right on a test patch before the real thing`, `Clean lines. You're ready. (Spanner nods.)`, `Drips everywhere. Spanner laughs. Try again.`],
          ['grt', 'easy', `Stick at it if the first go is a Proper Mess, and repaint it`, `Second go. Much better. Pat claps.`, `You sulk. Pat pats your arm. "Next time."`]]}
    ],
    closeTitle: `Read aloud: Pat's verdict`,
    close: `Pat stands back from the wall with her glasses on the end of her nose and looks at your tag for a long time. "Well," she says. "It's not the Sistine Chapel." Spanner, in the doorway, snorts into his tea. Pat smiles. "But it's yours. And it's on my wall." She takes the can back. "Now everyone who brings me a bike knows who's working for me."`,
    notes: [`This is the tutorial. Let players experiment with Tag Studio and see the six quality tiers.`,
      `The wall is sanctioned: zero Heat.`,
      `A Proper Mess stays on the wall until repainted. That's intended. It's a lesson, not a punishment.`,
      `Reward: £15. Leads to TG-INTRO-02.`]
  },
  'tg-intro-02': {
    brief: `A courier and a radio runner want proof the same mark can cross neighbourhoods. The crew paint two walls on two different maps (the Kingsland courier arch and the Queensbridge Sound Store hire shutter) and show the in-game graffiti album as proof. The twist: a local witness recognises the mark later. Heat depends on visibility, not a guaranteed star.`,
    openTitle: `Read aloud: walls have ears`,
    open: `Kez skids up on his BMX with a courier you don't know: a woman in a cycling jacket with a radio runner's lanyard. "She reckons a tag can't cross the canal," Kez says. "Reckons nobody in Haggerston cares what's on a wall in Dalston." The courier shrugs. "Prove me wrong. Two walls. Two neighbourhoods. Same mark. Photos in your album." She grins. "Tenner says you can't."`,
    cast: ['kez', 'yasmin-dale', 'amina-keane'],
    roles: {kez: `Bet a tenner on the crew. Wants to win.`, 'yasmin-dale': `Fleet coordinator at the Kingsland Courier Arch. Doesn't mind a tag on her wall if it's good.`, 'amina-keane': `Owns the Queensbridge Sound Store. Minds very much about her hire shutter.`},
    scenes: [
      {at: 'SP-LF-KINGSLAND-ARCH', title: `The Kingsland courier arch wall`, read: `Under the railway on Kingsland High Street, the Courier Arch's side wall: bare brick between a cycle rack and a bus stop. Couriers come and go every thirty seconds. Yasmin Dale, sunglasses on her head, watches you shake the can. "If it's good, it stays," she says. "If it's rubbish, you're scrubbing it off yourself."`,
        text: `Paint with the Graft roll from Tag Studio. The bus stop is busy: a witness here is possible.`,
        checks: [['sav', 'easy', `Pick the gap between buses when nobody's at the stop`, `Thirty clear seconds. Perfect.`, `A bus pulls in mid-tag. Twelve people watch.`]]},
      {at: 'SP-HR-QUEENSBRIDGE', title: `The Queensbridge Sound Store hire shutter`, read: `Queensbridge Road at dusk. The Sound Store's hire shutter is down for the night: corrugated steel, already covered in faded stickers. Amina Keane's van is parked outside. Her flat's upstairs. Her light is on.`,
        text: `A shutter, not a wall. Paint fast and get the album photo. A witness here recognises the mark later; Heat depends on whether anyone saw.`,
        checks: [['mov', 'medium', `Keep to the shadows under the shop awning so Amina doesn't see from upstairs`, `Unseen. Tag done, photo taken.`, `Her curtain twitches.`],
          ['btl', 'easy', `If Amina opens the window and shouts, stand there and finish the tag`, `She watches, then nods. "Not bad." Window shuts.`, `You run. Half a tag.`]]}
    ],
    closeTitle: `Read aloud: a tenner`,
    close: `The courier scrolls through your album on her phone: the Kingsland arch, the Queensbridge shutter, same mark, two neighbourhoods. She hands Kez a tenner without a word. Kez waves it in the air like a trophy. "Told you," he says. "Walls have ears. And eyes." He looks at your tag on the screen. "And now they've got your name."`,
    notes: [`Two different map IDs, and album photos as proof. No real camera item needed.`,
      `A witness might recognise the mark later. Heat depends on visibility, not a guaranteed star.`,
      `Reward: £35. Leads to TG-INTRO-03.`]
  },
  'tg-intro-03': {
    brief: `Put the crew's mark on two parked buses on different streets (London Fields and Waterden Road), then leave before they go back into service. This is the moving-asset test: the tag follows the bus. Buses must be stationary while painting. The twist: the second bus is from a different depot; only a real painted token counts.`,
    openTitle: `Read aloud: the last bus home`,
    open: `Kez shows you a photo on his phone: a bus in Peckham with a tag down the side that has been all over London, seen by a million people. "That's the dream," he says. "Your name, going round the city while you sleep." He swipes. "Two buses parked up tonight. One at London Fields. One at Waterden Road. Driver's break, twenty minutes each." He grins. "Last bus home."`,
    cast: ['kez'],
    roles: {kez: `Scouts the parked buses and times the driver's breaks.`},
    scenes: [
      {at: 'SP-LF-LIDO-BUS', title: `The London Fields stationary bus`, read: `By the Lido at London Fields, a single-decker sits with its doors closed and its engine off. The driver is in the café across the road with a tea, watching football on his phone. Twenty minutes, Kez says. The side of the bus is clean and white and very, very tempting.`,
        text: `Paint while the bus is stationary. The time goes on the Banana Watch (buses take an extra minute).`,
        checks: [['sav', 'medium', `Keep one eye on the driver in the café while you paint`, `He stands up as you finish. You're round the corner.`, `He comes out mid-tag. "Oi!"`],
          ['mov', 'easy', `Get away across the park before the driver reaches the bus`, `Across the grass and gone.`, `He gets a good look at you.`]]},
      {at: 'SP-VW-WATERDEN-BUS', title: `The Waterden Road parked bus`, read: `Waterden Road by the Olympic Park: a parked double-decker at the end of its route, lights off. This one's from a different depot: newer, cleaner, and with a CCTV camera on the front.`,
        text: `Only a real painted token counts. The camera faces forward; paint the side.`,
        checks: [['aim', 'medium', `Throw your hoodie over the front camera from the kerb so it can't see the side`, `Draped perfectly. The camera films cotton.`, `It slides off.`],
          ['whl', 'medium', `Get away on your bikes before the next driver arrives for his shift`, `Down Waterden Road and onto the towpath.`, `His car pulls up as you leave.`]]}
    ],
    closeTitle: `Read aloud: going round the city`,
    close: `Next morning, Kez sends you a video: the London Fields bus pulling away from the Lido on its first run of the day, your tag down its side, past a queue of people at the stop. "Seen by forty-two people before Mare Street," he says. "I counted." He sends another: the Waterden Road bus, heading for Stratford. "Your name," he says. "Going round the city while you sleep."`,
    notes: [`The buses must be stationary while painting. The tag follows the bus token afterwards.`,
      `The second bus is from a different depot. Only a real painted token counts.`,
      `Reward: £60. Leads to TG-INTRO-04.`]
  },
  'tg-intro-04': {
    brief: `Three bridges across three maps: a Clapton canal footbridge support, a Bow Flyover column and a Carpenters Road bridge pier. Readable marks, no duplicate locations. This is the cross-district bridge sequence (no unsafe climbing). The twist: it unlocks the Crew Identity slot in the Tagbook.`,
    openTitle: `Read aloud: a name that travels`,
    open: `Kez spreads a map on the bonnet of a car and draws three circles: Clapton, Bow, Stratford. "Three bridges," he says. "Three corners of the patch. Do these and you're not just some crew with a can." He taps the map. "You're a name." He folds it up. "Everyone who drives under the Bow Flyover sees it. Every single day."`,
    cast: ['kez', 'ezra-holt'],
    roles: {kez: `Plans the route. Very excited.`, 'ezra-holt': `Rows under the Clapton footbridge every morning. Will see the tag first.`},
    scenes: [
      {at: 'SP-CL-TOWPATH', title: `The Clapton canal footbridge support`, read: `The towpath at Clapton at dawn: mist on the Lea, a heron on a mooring post, rowers sliding past. The footbridge support is a concrete column at the water's edge. A youth rowing crew glides by; their coach, Ezra Holt, waves.`,
        text: `Paint the support from the towpath. Bridges add two minutes on the Watch.`,
        checks: [['grt', 'easy', `Paint in the cold dawn mist with numb fingers`, `Steady hands. Clean lines.`, `Your fingers shake. It's ragged.`]]},
      {at: 'SP-BF-PILLAR', title: `The Bow Flyover column`, read: `Under the Bow Flyover, the noise is like standing inside a drum: lorries thundering overhead, the roundabout roaring around you. The column is huge, grey and covered in old tags. There's one clean patch at head height.`,
        text: `Busy, loud and visible. A patrol car circles the roundabout every few minutes.`,
        checks: [['sav', 'medium', `Time the patrol car's loop round the roundabout`, `Four minutes a loop. You paint in the gap.`, `It comes round early.`],
          ['mov', 'medium', `Cross the roundabout to the column safely between lorries`, `Across in one gap.`, `A lorry blares its horn. Everyone looks.`]]},
      {at: 'SP-ST-CARPENTERS', title: `The Carpenters Road bridge pier`, read: `Carpenters Road in Stratford, under a railway bridge. The pier is brick, curved, and lit by one orange street lamp. It's quiet: just a fox and a man walking a dog.`,
        text: `The last bridge. Completing all three unlocks the Crew Identity slot in the Tagbook.`,
        checks: [['btl', 'easy', `Keep painting when the dog walker stops to watch`, `He nods. "Nice." He walks on.`, `You stop. He walks on. You start again, rattled.`],
          ['whl', 'easy', `Get the crew home across three districts before dawn`, `Home by six.`, `Lost in Stratford's one-way system.`]]}
    ],
    closeTitle: `Read aloud: a name`,
    close: `Kez stands under the Bow Flyover the next morning, looking up at your tag as the traffic roars past. "Every single day," he says. "Thousands of people." He takes a photo. "You're not just some crew with a can now." He grins. "You're a name." On your phone, the Tagbook pings: a new slot has opened. CREW IDENTITY.`,
    notes: [`Cross-district bridge sequence. No unsafe climbing: all three are reachable from the ground.`,
      `Completing it unlocks the Crew Identity slot in the Tagbook.`,
      `Reward: £100. Leads to TG-CITY-01 later.`]
  },
  'tg-ch-01': {
    brief: `Pat marks trusted collection and drop-off points for the Chainring. The first run is a local network test: the Morning Lane workshop wall and the Chainring Storehouse boundary wall, both with the Chainring Cog tag. A sanctioned shop wall gives zero criminal Heat. The twist: the wrong marking can misroute a stolen bike.`,
    openTitle: `Read aloud: the arches signal`,
    open: `Pat draws a little cog on a Post-it with a biro: eight teeth, a circle in the middle. "The Chainring Cog," she says. "Where you see this, you can drop a bike and someone'll collect it. Where you don't, you don't." She sticks the Post-it on the workbench. "Two walls to start. Mine and the Storehouse." She looks at you. "And get the teeth right. Eight. Not seven. Seven means something else."`,
    cast: ['auntie-pat', 'spanner-rob', 'kez'],
    roles: {'auntie-pat': `Designs the network. Very particular about the number of teeth.`, 'spanner-rob': `Will collect from the Storehouse mark.`, kez: `Runs the bikes. Needs to be able to read the marks at speed.`},
    scenes: [
      {at: 'SP-HC-MORNING-WALL', title: `The Morning Lane workshop wall`, read: `Pat's wall again, beside your old practice tag. Pat stands next to you with the Post-it. "Eight teeth," she says. "Count them."`,
        text: `The Chainring Cog tag, on a sanctioned wall. Zero Heat.`,
        checks: [['aim', 'easy', `Get all eight teeth crisp and evenly spaced`, `Eight perfect teeth. Pat counts them twice. "Lovely."`, `Seven and a bit. Pat frowns. "Do it again."`]]},
      {at: 'SP-HC-STOREHOUSE', title: `The Chainring Storehouse boundary wall`, read: `Behind Morning Lane, the Storehouse's boundary wall faces the van court. Spanner Rob waits at the roller door with his tea. "Make it big enough to see from a bike," he says. "At speed. In the rain."`,
        text: `The second mark. The twist: a wrong marking can misroute a stolen bike. Kez tests it.`,
        checks: [['whl', 'medium', `Ride past the mark at speed on a bike to check it's readable`, `Clear as day at twenty miles an hour.`, `You can't read it. Paint it bigger.`],
          ['mus', 'easy', `Move the skip blocking the best spot on the wall`, `Shifted. Clear wall.`, `It won't budge. Paint round it.`]]}
    ],
    closeTitle: `Read aloud: eight teeth`,
    close: `That night, Kez drops a nicked bike at the Storehouse mark. By morning, Spanner has collected it, stripped it and sent it on its way. Pat counts the teeth on the wall one more time, nods, and goes back inside. "Seven teeth," she says over her shoulder, "means the Old Bill are watching. Don't ever paint seven." She shuts the shutter. "Unless they are."`,
    notes: [`A sanctioned shop wall gives zero criminal Heat.`,
      `The Chainring Cog has eight teeth. Seven means police are watching (Pat's code).`,
      `Reward: £65. Leads to TG-CH-02.`]
  },
  'tg-ch-02': {
    brief: `Carry the Chainring Cog from its new supplier through the rival corridor: the Oddments Lockup yard wall, the Lea Bridge Social Rooms side wall (Lea Boys territory) and the Bow Breakers Yard exterior wall. Every mark must be Sorted or better. One existing Lea Boys mark is a contest slot: overpainting it is an explicit choice. The twist: the Lea Boys already consider one wall theirs.`,
    openTitle: `Read aloud: spokes across Hackney`,
    open: `Pat draws a line on a map from Highbury to Bow, right through Clapton. "New supplier at the Oddments Lockup. New buyer at Bow Breakers." She taps Clapton. "And this bit in the middle is Stretch's." She puts the pen down. "Three walls. Sorted or better. No scruffy ones." She looks at you over her glasses. "There's a Lea Boys mark on the Social Rooms wall. You can paint next to it, or over it." She smiles. "Your choice, darlings."`,
    cast: ['auntie-pat', 'ruth-bellamy', 'tessa-price'],
    people: {'big-den': {name: 'Big Den', role: 'Bow Breakers Yard, Roman Road', img: 'systems/the-smoke/assets/tokens/people/ped-17.webp'}},
    roles: {'auntie-pat': `Wants the cog across Hackney.`, 'ruth-bellamy': `Lets you use the Oddments Lockup yard wall.`, 'tessa-price': `Moth. Watches the Social Rooms wall.`, 'big-den': `Lets you paint his yard wall, if you're quick.`},
    scenes: [
      {at: 'SP-HB-ODDMENTS', title: `The Oddments Lockup yard wall`, read: `The Oddments Lockup's loading court. Ruth Bellamy jangles her keys. "Pat's mark? Fine. Just don't get paint on the shutter." The wall is pale render, perfect for paint.`,
        text: `Sorted or better needed.`,
        checks: [['grt', 'easy', `Prime the rough render with three coats first`, `Smooth as glass. Ready.`, `It drinks the paint. Patchy.`]]},
      {at: 'SP-CL-LEABRIDGE', title: `The Lea Bridge Social Rooms side wall`, read: `The side wall of the Lea Bridge Social Rooms, facing the car park. A Lea Boys reed mark is already there, freshly painted. Moth sits on a bench across the car park, watching you. She doesn't say anything.`,
        text: `The contest slot. Overpainting the Lea Boys mark is an explicit choice: it starts a contest. Painting beside it doesn't.`,
        checks: [['btl', 'medium', `Paint with Moth watching, and decide: beside the reed, or over it`, `Whatever you choose, you choose it calmly. Moth nods once.`, `You hesitate. Moth stands up.`],
          ['frt', 'medium', `Walk over and ask Moth's permission`, `"Beside it. Not over it." Fair enough.`, `"Ask Stretch." Unhelpful.`]]},
      {at: 'SP-OF-BREAKERS', title: `The Bow Breakers Yard exterior wall`, read: `The corrugated fence of Bow Breakers on Roman Road. Big Den is in the yard with the crane. "Paint what you like," he shouts. "But I'm moving a car in five minutes and it's coming through that gate."`,
        text: `Five minutes before the crane comes through.`,
        checks: [['mov', 'medium', `Finish and get clear before the crane swings a car through the gate`, `Done and out of the way with a second to spare.`, `You dive clear. The tag is half done.`],
          ['whl', 'easy', `Get across from Clapton to Bow in time`, `Arrive as Den's starting the crane.`, `Den's already moving the car.`]]}
    ],
    closeTitle: `Read aloud: across Hackney`,
    close: `Pat traces the line on her map with a finger: Highbury, Clapton, Bow, three cogs, eight teeth each. "Across Hackney," she says. Then she looks at you. "And the Social Rooms?" You tell her what you chose. She is quiet for a moment. "Well," she says. "Stretch will have an opinion." She folds the map. "He always does."`,
    notes: [`Every mark must be Sorted or better.`,
      `The Lea Boys mark at the Social Rooms is a contest slot. Overpainting it is an explicit choice that affects LB stance.`,
      `Reward: £130 and 1 CH Renown. Leads to TG-CH-03.`]
  },
  'tg-ch-03': {
    brief: `Paint three types of transport-side frontage and bring a photo set back to Pat: a Temple Mills depot carriage, the Waterden Road parked bus and the Round Chapel event-load shutter. Each at least Just About; the best one must be Smashed It or better. The twist: a legitimate owner offers to sell the tagged bus back to its operator.`,
    openTitle: `Read aloud: Pat owns the route`,
    open: `Pat has a photo album open on her workbench: the Morning Lane wall, the Storehouse, Oddments, the Social Rooms, Bow Breakers. "Walls," she says. "Lovely. But walls don't move." She turns a page to an empty one. "A train. A bus. A van shutter. Things that go places." She taps the page. "And one of them, darlings, I want to be the best thing you've ever done."`,
    cast: ['auntie-pat', 'kez'],
    roles: {'auntie-pat': `Wants the cog on things that move. One masterpiece.`, kez: `Scouts the train and bus.`},
    scenes: [
      {at: 'SP-HM-TEMPLE-TRAIN', title: `The Temple Mills depot carriage`, read: `Temple Mills depot at night: long sleek carriages lined up in the yard, lit by floodlights, the hum of electrics. One carriage, out of service, sits at the end of a siding by the fence.`,
        text: `A stationary carriage prop only. Trains add three minutes on the Watch.`,
        checks: [['mov', 'medium', `Get through the gap in the depot fence without catching on the wire`, `Through clean.`, `Your sleeve tears. The wire rattles.`],
          ['sav', 'medium', `Spot the depot's security patrol before they spot you`, `Torch beam at the far end. You've got eight minutes.`, `The torch is on you.`]]},
      {at: 'SP-VW-WATERDEN-BUS', title: `The Waterden Road parked bus`, read: `The Waterden Road bus again, parked up for the night. Someone else's tag is already on the front. Yours goes down the side.`,
        text: `The twist: a man in a hi-vis comes over afterwards and offers to "sell the tagged bus back to its operator" as art. He's a chancer.`,
        checks: [['frt', 'easy', `Send the chancer packing`, `He leaves. "Your loss."`, `He follows you down the road.`]]},
      {at: 'SP-HC-ROUND-SHUTTER', title: `The Round Chapel event-load shutter`, read: `The loading court at the Round Chapel. The event-load shutter is tall, wide and freshly painted grey by the venue. It's the best canvas you've ever seen.`,
        text: `Go for Smashed It here. Take your time: take an extra minute on the Watch for a better design.`,
        checks: [['grt', 'medium', `Spend an hour on the design, layering and detailing`, `It's the best thing you've ever done.`, `You rush the last layer.`],
          ['aim', 'medium', `Use a thrown roller on an extending pole to reach the top of the shutter`, `Perfect coverage, top to bottom.`, `Splat. Repaint.`]]}
    ],
    closeTitle: `Read aloud: the best thing you've ever done`,
    close: `Pat goes through the photo set slowly: the carriage, the bus, and then the Round Chapel shutter. She stops on that one. She takes her glasses off. She puts them back on. "Well," she says, very quietly. "Well, well." She slides the photo into the album and closes it. "Pat owns the route," she says. Then she looks at you. "And you, my darlings, own that shutter."`,
    notes: [`Each mark at least Just About; the best must be Smashed It or better.`,
      `The train carriage must be a stationary prop.`,
      `A chancer offers to sell the tagged bus back to its operator. Ignore or play it for laughs.`,
      `Reward: £220. Completes the CH tagging line.`]
  },
  'tg-ad-01': {
    brief: `Patch issues a two-wall Dead Air stencil campaign before the next broadcast: the Queensbridge Sound Store hire shutter and the Backspin Studio loading shutter. A branded stencil kit can be collected from Backspin as optional mission cargo. The twist: a rival pirate show has booked the same walls.`,
    openTitle: `Read aloud: get the signal out`,
    open: `Patch holds up a stencil cut from an old vinyl sleeve: a radio wave, three curved lines, and DEAD AIR in block capitals. "Big up the crew," he says. "Two walls before Friday's show. Queensbridge and our own shutter." He hands you the stencil. "When people see this, they tune in." He grins. "That's the plan. Get the signal out."`,
    cast: ['jules-akin', 'dee-hassan', 'amina-keane'],
    roles: {'jules-akin': `Patch. Wants the signal out before Friday.`, 'dee-hassan': `Cut the stencil. Will fix it if it breaks.`, 'amina-keane': `Owns the Queensbridge shutter. Tolerates Dead Air.`},
    scenes: [
      {at: 'SP-DA-BACKSPIN', title: `The Backspin Studio loading shutter`, read: `The rear stair at Backspin Studio, the loading shutter at the bottom. Dee Hassan hands you a stencil kit in a carrier bag: two stencils, tape, masking paper. "Don't spoof the radio sender," she says. "We're Dead Air. Just Dead Air."`,
        text: `The branded stencil kit is optional cargo. A sanctioned wall.`,
        checks: [['aim', 'easy', `Line the stencil up dead straight and spray it clean`, `Crisp edges. Perfect wave.`, `It slips. Fuzzy edges.`]]},
      {at: 'SP-HR-QUEENSBRIDGE', title: `The Queensbridge Sound Store hire shutter`, read: `Queensbridge Road at midnight. The hire shutter has fresh masking tape on it already, and a stencil half-sprayed: a lightning bolt and the words RUDE BOY RADIO. A rival pirate show. They've gone round the corner for more paint.`,
        text: `The twist: a rival show has booked the same wall. Paint beside, paint over, or wait.`,
        checks: [['btl', 'medium', `Stand your ground when the rival show's crew come back`, `They look at your wave, then at you. "Fair. Share it?"`, `They square up.`],
          ['mus', 'easy', `Move the rival's ladder so you can reach the clean space`, `Moved. Space clear.`, `It clatters over.`]]}
    ],
    closeTitle: `Read aloud: tune in`,
    close: `On Friday night, Patch opens the show with a shout-out. "Big up whoever painted the wave on Queensbridge," he says, live. "Big up the crew." The phone lines light up: four, then ten, then twenty listeners, all saying they saw the wave and tuned in. Dee, at the desk, gives you a thumbs-up. "Get the signal out," she says. "Done."`,
    notes: [`The stencil kit from Backspin is optional mission cargo.`,
      `Do not spoof the radio sender: the tag is Dead Air's own wave.`,
      `Reward: £65. Leads to TG-AD-02.`]
  },
  'tg-ad-02': {
    brief: `Dee commissions three venue panels ahead of a live set, each in a different neighbourhood: the Shacklewell Arms loading shutter, the Bridge Nine broadcast garage shutter and the Hoxton Hall authorised display board. Each must show the Dead Air wave, not a generic crew image, at Sorted or better. The twist: one tag is legal promotional art; another is disputed.`,
    openTitle: `Read aloud: the frequency run`,
    open: `Dee Hassan doesn't do speeches. She hands you a list on a Post-it: SHACKLEWELL. BRIDGE NINE. HOXTON HALL. "Three panels before the live set," she says. "The wave, not your crew mark. Sorted or better." She goes back to her soldering. Then, without looking up: "Hoxton Hall said yes. Shacklewell didn't say no. Bridge Nine didn't answer."`,
    cast: ['dee-hassan', 'mags-cole', 'nico-evans'],
    roles: {'dee-hassan': `Commissions the run. Practical, impatient with drama.`, 'mags-cole': `At the Shacklewell. Might say no.`, 'nico-evans': `"Blank." Helps carry the paint.`},
    scenes: [
      {at: 'SP-HR-HOXTON', title: `The Hoxton Hall authorised display board`, read: `Hoxton Hall's display board, beside the main door on Hoxton Street. Authorised: the hall said yes. Nico "Blank" Evans holds the paint bag, headphones round his neck.`,
        text: `Legal promotional art. No Heat.`,
        checks: [['grt', 'easy', `Do it properly: three coats, careful edges`, `Sorted. Easily.`, `Rushed. Just About.`]]},
      {at: 'SP-SN-SHACKLEWELL', title: `The Shacklewell Arms loading shutter`, read: `The loading bay at the Shacklewell Arms. Mags Cole stands in the bay with her arms folded and gaffer tape on her wrist. "Didn't say no," she says. "Didn't say yes, either."`,
        text: `Disputed. Mags can be persuaded, or the crew can paint fast and go.`,
        checks: [['frt', 'medium', `Persuade Mags to say yes`, `"Fine. Make it good."`, `"No." Paint it and run, or don't.`],
          ['mov', 'medium', `Paint fast and get out over the yard wall if she says no`, `Over and gone.`, `She sees you go.`]]},
      {at: 'SP-ST-BRIDGE9', title: `The Bridge Nine broadcast garage shutter`, read: `Bridge Nine on Carpenters Road, under the railway. The OB van's garage shutter is down. Nobody answered Dee's message. There's a security light.`,
        text: `Unanswered. Treat as unauthorised. Heat applies if witnessed.`,
        checks: [['aim', 'medium', `Knock the security light's sensor off-angle with a thrown bottle cap`, `It points at the sky. Darkness.`, `It pings off. The light comes on.`],
          ['whl', 'medium', `Get from Stratford back to Dalston before the set starts`, `In the booth as the red light goes on.`, `Late.`]]}
    ],
    closeTitle: `Read aloud: three panels`,
    close: `Dee looks at your three photos on her phone, scrolling slowly. Hoxton Hall, the Shacklewell, Bridge Nine. The wave on each, crisp and clean. She says nothing for a while. Then: "Sorted." From Dee, that's a standing ovation. She puts the phone down and picks up her soldering iron. "Live in five," she says.`,
    notes: [`Each tag must show the Dead Air wave, not a generic crew image. Sorted or better.`,
      `Hoxton Hall is legal; Shacklewell is disputed; Bridge Nine is unanswered. Heat varies.`,
      `Reward: £130 and 1 AD Renown. Leads to TG-AD-03.`]
  },
  'tg-ad-03': {
    brief: `The station wants a citywide visual takeover of rail-themed props and an overbridge before its broadcast: an Orient Way yard carriage, a Pudding Mill Lane stationary DLR carriage and the Carpenters Road bridge pier. Each Just About or better; one Smashed It or better. Both train props must be stationary. The twist: a fake ident threatens to confuse which collective commissioned it.`,
    openTitle: `Read aloud: no dead air tonight`,
    open: `Patch is pacing. "Big night. Biggest show of the year. And somebody's been painting a fake Dead Air wave round Stratford." He shows you a photo: a wave with four lines instead of three. "Four lines! We've never had four lines!" He breathes. "I want the real wave on two trains and a bridge before we go on air. So people know which one's us."`,
    cast: ['jules-akin', 'dee-hassan'],
    roles: {'jules-akin': `Patch. Furious about the fake wave.`, 'dee-hassan': `Knows exactly how many lines the real wave has.`},
    scenes: [
      {at: 'SP-HM-ORIENT-TRAIN', title: `The Orient Way yard carriage`, read: `The Orient Way railway yard: a single carriage parked on a siding behind a fence, out of service. Someone has already painted a four-line wave on the end of it.`,
        text: `Stationary prop. Trains add three minutes on the Watch. Paint the real wave beside the fake.`,
        checks: [['sav', 'medium', `Spot the yard's camera blind spot`, `Behind the carriage, by the buffer stop. Clear.`, `You're in shot.`]]},
      {at: 'SP-BF-DLR', title: `The Pudding Mill Lane stationary DLR carriage`, read: `Pudding Mill Lane: a DLR carriage parked up out of service at the end of a siding, doors locked, lights off. Wind across the concrete.`,
        text: `Go for Smashed It here. Cold and windy.`,
        checks: [['grt', 'medium', `Keep your hands steady in the freezing wind for twenty minutes`, `Rock steady. Smashed It.`, `Shaky. Just About.`],
          ['btl', 'easy', `Keep going when a train goes past on the main line and the driver honks`, `You wave. He waves back.`, `You flinch and smudge it.`]]},
      {at: 'SP-ST-CARPENTERS', title: `The Carpenters Road bridge pier`, read: `The Carpenters Road pier again, under the orange lamp. The fox is back.`,
        text: `The last of three before the broadcast.`,
        checks: [['whl', 'medium', `Get back to Bridge Nine before the show goes live`, `In the van as the red light comes on.`, `You hear the opening on the car radio.`],
          ['mus', 'easy', `Shift the abandoned shopping trolley wedged against the pier`, `Moved. Clean pier.`, `It's stuck fast. Paint round it.`]]}
    ],
    closeTitle: `Read aloud: three lines`,
    close: `Live on air, Patch holds up his phone to the microphone as if listeners can see it. "Three lines," he says. "That's us. Three. If you see four, that's not us. That's a copy." He puts the phone down. "Big up the crew who painted the real ones on two trains and a bridge tonight. No dead air tonight, East London." He drops the first record. The bass hits.`,
    notes: [`Both train carriages must be stationary props. No active-train boarding.`,
      `Each Just About or better; one Smashed It or better.`,
      `The fake four-line wave is a hook for AD5 (the fake broadcast).`,
      `Reward: £220. Completes the AD tagging line.`]
  },
  'tg-lb-01': {
    brief: `A Lea Boys marker identifies contested drop points. Moth wants the reed at the Lea Bridge Social Rooms side wall and the Larch Cold Store outer wall. The first site is contested: repainting creates a tagged revision, not a second tile. The twist: the Night Market is using one site too.`,
    openTitle: `Read aloud: Moth leaves a sign`,
    open: `Moth draws a reed in her notebook: a single tall stem with a curved head, like a bulrush. "Lea Boys mark," she says. "Means a drop point. Means ours." She tears out the page and hands it to you. "Two walls. The Social Rooms and the Larch." She looks at you. "Someone's painted over the Social Rooms one. Put it back."`,
    cast: ['tessa-price', 'marta-severin'],
    people: {'pearl-okonkwo': {}},
    roles: {'tessa-price': `Moth. Wants the reed back on the Social Rooms wall.`, 'marta-severin': `Night manager at the Larch. Doesn't care about walls, cares about her shift.`, 'pearl-okonkwo': `The Night Market is using the Larch wall too.`},
    scenes: [
      {at: 'SP-CL-LEABRIDGE', title: `The Lea Bridge Social Rooms side wall`, read: `The side wall of the Social Rooms. Someone has painted over the old Lea Boys reed with a grey rectangle. Underneath, if you look closely, you can still see the reed's outline.`,
        text: `Contested. Repainting creates a revision, not a new tile.`,
        checks: [['mov', 'easy', `Get up on the wheelie bins to reach the top of the wall`, `Up and steady.`, `The bin lid cracks.`]]},
      {at: 'SP-LY-LARCH', title: `The Larch Cold Store outer wall`, read: `The Larch Cold Store's outer wall on Orient Way. There's already a mark on it: a lantern. The Night Market's sign. Marta Severin, on her smoke break by the lorry apron, shrugs. "Everyone wants my wall," she says. "Nobody asks."`,
        text: `The Night Market uses this site too. Paint beside the lantern, or over it.`,
        checks: [['frt', 'medium', `Ask Marta's permission, properly`, `"Fine. Not on the loading door."`, `"Not my wall. Ask head office."`],
          ['sav', 'medium', `Notice that the lantern mark is fresh: Pearl's people were here tonight`, `The paint's still wet. They might be back.`, `You don't notice.`],
          ['aim', 'medium', `Get the reed high up where nobody else can reach, with a can on a pole`, `Top of the wall. Nobody's painting over that.`, `Drips down onto the lantern.`]]}
    ],
    closeTitle: `Read aloud: ours`,
    close: `Moth looks at the photos: the reed back on the Social Rooms wall, the reed beside Pearl's lantern on the Larch. "Pearl's people," she says. "On the Larch." She thinks about it. "Fine. Share it." She closes her notebook. "Pearl's fair. Stretch wouldn't share. That's the difference."`,
    notes: [`The first site is contested: repainting creates a tagged revision, not a second tile.`,
      `The Night Market uses the Larch wall too. Overpainting affects NM stance.`,
      `Reward: £65. Leads to TG-LB-02.`]
  },
  'tg-lb-02': {
    brief: `Three waterside marks signal a new route through rival territory: the Clapton canal footbridge support, the Grow Hackney canal retaining wall and the Tern Wharf canal parapet. Sorted or better. A faction-stance branch: cooperate for a permitted tag variant, or contest it. The twist: the Towpath Union objects and offers an alternate commission.`,
    openTitle: `Read aloud: reeds by the water`,
    open: `Moth walks you along the towpath at Clapton, pointing. "The canal's a road," she says. "For bikes, for runners, for people who don't want to be seen on Mare Street." She stops by the footbridge. "Three reeds. Clapton, the Wick, Tern Wharf. A route." She looks at you. "Tern won't like it. Her drivers use the towpath." She shrugs. "That's her problem."`,
    cast: ['tessa-price', 'mara-boyd', 'eileen-grant'],
    roles: {'tessa-price': `Moth. Wants a Lea Boys route along the canal.`, 'mara-boyd': `Tern. Objects, and offers an alternate commission.`, 'eileen-grant': `At Grow Hackney. Doesn't want gang signs on her arts space.`},
    scenes: [
      {at: 'SP-CL-TOWPATH', title: `The Clapton canal footbridge support`, read: `The footbridge support at Clapton. Your earlier tag from the intro is already here. A heron watches from a moored boat.`,
        text: `Sorted or better.`,
        checks: [['grt', 'easy', `Paint in the drizzle without the colours running`, `Clean. Sorted.`, `It runs. Just About.`]]},
      {at: 'SP-VW-WICK-CANAL', title: `The Grow Hackney canal retaining wall`, read: `The canal retaining wall below Grow Hackney's greenhouses. Eileen Grant leans over the railing above with her clipboard. "Not a gang sign," she says. "Not on our wall."`,
        text: `Cooperate (a permitted variant) or contest.`,
        checks: [['frt', 'medium', `Negotiate a permitted variant with Eileen: the reed as part of a mural`, `"A reed in a landscape? Fine. That's art."`, `"No."`],
          ['mov', 'medium', `Paint from a narrowboat's roof, moored below`, `Steady on the roof. Done.`, `The boat rocks. You nearly go in.`]]},
      {at: 'SP-HX-TERN', title: `The Tern Wharf canal parapet`, read: `The canal parapet at Tern Wharf. Mara "Tern" Boyd stands on it with her arms folded and her headset on. "My drivers use this towpath," she says. "I don't want Lea Boys signs telling them whose it is." She holds out a piece of paper. "Paint my mark instead. I'll pay double."`,
        text: `The Towpath Union objects and offers an alternate commission. A faction-stance branch.`,
        checks: [['btl', 'medium', `Choose, out loud, between Moth's reed and Tern's commission`, `Whatever you choose, both respect you for saying it to their face.`, `You dither. Both are annoyed.`],
          ['whl', 'medium', `Ride the towpath route on bikes to test it's real`, `Clapton to Hoxton in eighteen minutes, unseen.`, `You get lost at the Wick.`]]}
    ],
    closeTitle: `Read aloud: whose towpath`,
    close: `Moth and Tern meet on the towpath at Tern Wharf, for the first time, with you between them. "My route," Moth says. "My drivers," Tern says. They look at the parapet, at whatever you painted there. Then Tern laughs. "Fine. Share it. Your lot keep off it in the mornings; my lot keep off it at night." Moth thinks. Then she nods. "Deal."`,
    notes: [`Sorted or better.`,
      `A faction-stance branch: cooperate for a permitted variant, or contest it. The Towpath Union offers an alternate commission.`,
      `Reward: £130 and 1 LB Renown (or TU, if the crew took Tern's job). Leads to TG-LB-03.`]
  },
  'tg-lb-03': {
    brief: `Spread the reed across park, footbridge and overpass while a patrol is active: the Marshes pavilion boundary wall, the VeloPark approach footbridge panel and the East Cross overpass pillar. One high-risk spot; no real-world evasion choreography. Each Just About or better; one Smashed It. The twist: the supposed Lee Valley ally is a Backroom bookmaker.`,
    openTitle: `Read aloud: stretch out the borough`,
    open: `Moth has a contact. "Bloke in Lee Valley says he'll look after the reed out there. Keep it clean. Tell me who paints over it." She shows you a text from a number you don't know: "Leave it with me, love." She frowns. "Three more reeds. The Marshes, the VeloPark, the East Cross overpass." She looks up. "There's a patrol car on the A12 tonight. Mind it."`,
    cast: ['tessa-price', 'ollie-grant'],
    people: {'victor-randle': {}},
    roles: {'tessa-price': `Moth. Expanding the reed.`, 'ollie-grant': `Groundsman at the Marshes. Hates people on his grass.`, 'victor-randle': `The "Lee Valley ally". Actually Vic.`},
    scenes: [
      {at: 'SP-HM-NORTH-PAVILION', title: `The Marshes pavilion boundary wall`, read: `The boundary wall of the North Pavilion on Hackney Marshes, in the dark. Ollie Grant's strimmer is propped against it. Ollie himself is asleep in his van.`,
        text: `Quiet. Don't wake Ollie.`,
        checks: [['mov', 'easy', `Cross the pitches in the dark without leaving footprints on Ollie's lines`, `Not a mark on the grass.`, `Footprints across pitch 12. Ollie will be furious.`]]},
      {at: 'SP-ON-VELO', title: `The VeloPark approach footbridge panel`, read: `The footbridge to the VeloPark, a panel at the top of the ramp. A man in a camel coat is waiting at the bottom of the ramp, smoking a cigar. "Moth's friends?" he says. "Vic Randle. I'm the Lee Valley ally." He smiles. "Moth doesn't know that yet."`,
        text: `The twist: the ally is Vic.`,
        checks: [['sav', 'medium', `Work out what Vic's getting out of "looking after" the reed`, `He'll use it to mark where his collectors can find Lea Boys debtors.`, `He seems friendly.`],
          ['aim', 'medium', `Paint the high panel from the ramp with a can on a pole`, `Smashed It.`, `Drips. Just About.`]]},
      {at: 'SP-WW-EASTCROSS', title: `The East Cross overpass pillar`, read: `The East Cross overpass on the A12. Lorries overhead. A patrol car is parked on the slip road with its lights off, engine running. The pillar is fifty metres away, in full view.`,
        text: `The high-risk spot. A patrol is active.`,
        checks: [['btl', 'hard', `Paint in full view of a parked patrol car, calmly, like you belong there`, `They don't even look up. Done.`, `The lights come on. One star.`],
          ['whl', 'medium', `Get away before the patrol car pulls out`, `Off the slip road and gone.`, `They follow you for a mile.`]]}
    ],
    closeTitle: `Read aloud: the Lee Valley ally`,
    close: `Moth reads Vic Randle's name on your phone and closes her eyes. "Vic," she says. "The Lee Valley ally is Vic." She opens them. "He's going to use my reeds to find my lads who owe him." She tears a page out of her notebook and screws it up. "Paint over the VeloPark one," she says. "Tomorrow." She throws the paper in the bin. "Nobody uses the reed but us."`,
    notes: [`One high-risk spot (East Cross). No real-world evasion choreography.`,
      `Each Just About or better; one Smashed It or better.`,
      `The "ally" being Vic links to BB.`,
      `Reward: £220. Completes the LB tagging line.`]
  },
  'tg-vc-01': {
    brief: `Owen Pike books two gig-promo murals ahead of an opening: the Dalston Superstore authorised panel and the Hackney Empire loading shutter. Permitted show-panel variants; no criminal Heat if permission is upheld. The twist: the performer wants an unpaid name removed from the poster.`,
    openTitle: `Read aloud: tonight only`,
    open: `Owen hands you a printed poster: TONIGHT ONLY — THE VELVET CIRCUIT PRESENTS — and six names in decreasing size. "Two murals, babe," he says. "Superstore and the Empire's loading shutter. Big, bold, gorgeous." He taps the poster. "All six names. Exactly like this."`,
    cast: ['owen-pike', 'mara-sol'],
    roles: {'owen-pike': `Wants the poster painted exactly as printed.`, 'mara-sol': `The headliner. Wants an unpaid name removed.`},
    scenes: [
      {at: 'SP-DA-SUPERSTORE', title: `The Dalston Superstore authorised panel`, read: `The authorised panel beside Dalston Superstore's door: a big blank board, primed white, with "VELVET CIRCUIT" painted at the top already. Pink neon from the bar spills across it.`,
        text: `Permitted. No Heat.`,
        checks: [['aim', 'medium', `Get six names in perfectly graded sizes on a big board`, `Sorted: crisp, level, readable from across the road.`, `The last name is squashed.`]]},
      {at: 'SP-HC-EMPIRE-BAY', title: `The Hackney Empire loading shutter`, read: `The loading court behind the Hackney Empire. As you set up, Mara Sol comes out of the stage door in stage makeup. She looks at the poster in your hand. "Third name down," she says. "Kai. He's not being paid. Owen's using his name to sell tickets." She looks at you. "Leave him off."`,
        text: `The twist: the performer wants an unpaid name removed.`,
        checks: [['btl', 'medium', `Decide, and tell Owen to his face, whether Kai's name goes on`, `Owen shrugs. "Fine. Your call." He's annoyed.`, `You paint it on anyway. Mara walks off.`],
          ['mus', 'easy', `Set up the scaffold tower to reach the top of the shutter`, `Up and steady.`, `It wobbles.`]]}
    ],
    closeTitle: `Read aloud: tonight only`,
    close: `The two murals glow under the street lights: VELVET CIRCUIT, TONIGHT ONLY. Owen stands in front of the Empire mural with his arms out, delighted. "Gorgeous," he says. "Gorgeous." Then he counts the names. If there are five, he frowns. If there are six, Mara Sol, behind him, looks at you and doesn't say anything at all.`,
    notes: [`Permitted show-panel variants: no criminal Heat if permission is upheld.`,
      `The unpaid name is a small moral choice with a VC stance effect.`,
      `Reward: £65. Leads to TG-VC-02.`]
  },
  'tg-vc-02': {
    brief: `Three venue-side pieces build the Circuit's show circuit: the Rio Cinema side service shutter, the Wenlock Arms side mural wall and the Union Chapel event display wall. Sorted or better. The twist: a Dead Air agent asks for shared credits.`,
    openTitle: `Read aloud: the velvet trail`,
    open: `Owen spreads a map on the bar at the Blue Hour. "The Velvet Trail," he says. "Rio, Wenlock, Union Chapel. Three venues, three pieces, one look." He hands you a mood board: deep purple, gold leaf, a curling V. "Sorted or better, babe. I want people to follow it like a treasure hunt."`,
    cast: ['owen-pike', 'jules-akin'],
    roles: {'owen-pike': `Wants a trail of venue art.`, 'jules-akin': `Patch. Asks for Dead Air to share the credits.`},
    scenes: [
      {at: 'SP-DA-RIO', title: `The Rio Cinema side service shutter`, read: `The side service shutter at the Rio Cinema on Kingsland High Street. A film is letting out; people stream past.`,
        text: `Busy street. Paint between crowds.`,
        checks: [['sav', 'easy', `Time the paint between film showings when the street's quiet`, `Twenty quiet minutes. Done.`, `A crowd comes out mid-paint and watches.`]]},
      {at: 'SP-HX-WENLOCK', title: `The Wenlock Arms side mural wall`, read: `The side wall of the Wenlock Arms, already used for murals. Patch from Dead Air leans against it with a coffee. "Owen's trail," he says. "Nice." He sips. "Put the wave on it too. Shared credits. Dead Air and the Circuit. Everyone wins."`,
        text: `The twist: a Dead Air agent asks for shared credits.`,
        checks: [['frt', 'medium', `Broker shared credits between Patch and Owen on the phone`, `Owen sighs. "Fine. Small wave."`, `Owen says no. Patch says yes. You choose.`],
          ['grt', 'easy', `Spend three hours on the gold-leaf detail`, `It glows. Sorted easily.`, `Rushed.`]]},
      {at: 'SP-CG-UNION', title: `The Union Chapel event display wall`, read: `The event display wall at the Union Chapel on Compton Terrace: a big wall beside the church, lit by a lamp. A wedding party is coming out of the chapel.`,
        text: `Permitted display wall. Wait for the wedding to clear.`,
        checks: [['btl', 'easy', `Keep painting calmly as the wedding guests stop to watch`, `The bride asks for a photo with it.`, `You freeze. The guests drift off.`],
          ['whl', 'medium', `Get across from Hoxton to Canonbury before the wall's booked for another poster`, `First there.`, `Someone else is putting up a poster.`]]}
    ],
    closeTitle: `Read aloud: the trail`,
    close: `Owen walks the Velvet Trail himself the next evening: the Rio, the Wenlock, the Union Chapel. At each one he stops, admires it and takes a selfie. At the Wenlock, he spots the little Dead Air wave in the corner (if it's there) and rolls his eyes. "Patch," he says. "Always Patch." But he takes a selfie with that one too.`,
    notes: [`Sorted or better.`,
      `Shared credits with Dead Air is optional; it affects AD and VC stance.`,
      `Reward: £130 and 1 VC Renown. Leads to TG-VC-03.`]
  },
  'tg-vc-03': {
    brief: `Advertise the grand event from shopping frontage to transport and flyover: the Stratford loading-bay wall, the London Fields stationary bus and the Bow Flyover column. A branching permitted vs illicit route; tags use the same quality rule either way. One Smashed It or better. The twist: the venue forbids the final site. Do the crew take the approved substitute?`,
    openTitle: `Read aloud: full house, full city`,
    open: `Owen is very excited. "The grand event, babe. The biggest night of the year. I want it everywhere." He counts on his rings. "Westfield. A bus. The Bow Flyover." He grins. "Full house. Full city." Then his phone buzzes. He reads it. His grin fades slightly. "The flyover people say no." He shrugs. "Do it anyway. Or don't. Up to you."`,
    cast: ['owen-pike', 'maya-foster'],
    roles: {'owen-pike': `Wants the event advertised everywhere.`, 'maya-foster': `Personal shopper at Westfield. Can get you into the loading bay.`},
    scenes: [
      {at: 'SP-ST-WESTFIELD', title: `The Stratford loading-bay wall`, read: `The loading bay at Westfield Stratford City: lorries, roll cages, a huge blank wall. Maya Foster waves you in with a lanyard. "Twenty minutes," she says. "Then the next delivery."`,
        text: `Permitted, via Maya.`,
        checks: [['grt', 'easy', `Paint the huge wall in twenty minutes flat`, `Done as the lorry reverses in.`, `Half done.`]]},
      {at: 'SP-LF-LIDO-BUS', title: `The London Fields stationary bus`, read: `The London Fields bus again, parked up by the Lido. The driver is in the café. Your old tag is still on the other side.`,
        text: `Unpermitted: Heat applies if witnessed.`,
        checks: [['mov', 'medium', `Paint the side facing the park, out of the driver's sight`, `Unseen.`, `He comes out early.`]]},
      {at: 'SP-BF-PILLAR', title: `The Bow Flyover column`, read: `Under the Bow Flyover. The venue has forbidden this site, and offered an approved substitute: a hoarding round the corner. The flyover column is right there, huge and visible.`,
        text: `The twist: take the approved substitute, or paint the forbidden site. Go for Smashed It either way.`,
        checks: [['btl', 'medium', `Decide, and live with it: forbidden column or approved hoarding`, `You choose, and paint it like you mean it.`, `You dither, then rush it.`],
          ['aim', 'medium', `Paint the high section with a can on a pole`, `Smashed It.`, `Drips.`],
          ['whl', 'medium', `Get away from the roundabout before the patrol loop comes round`, `Gone.`, `Blue lights.`]]}
    ],
    closeTitle: `Read aloud: full house`,
    close: `On the night, the grand event sells out. Owen stands at the door in a new velvet blazer, counting people in. "Full house," he says. "Full city." He looks at you. "Which did you do? The flyover or the hoarding?" You tell him. He nods slowly. "Interesting choice," he says, and you can't tell whether he's pleased or not.`,
    notes: [`A branching permitted vs illicit route. The quality rule is the same either way.`,
      `One Smashed It or better.`,
      `Reward: £220. Completes the VC tagging line.`]
  },
  'tg-tu-01': {
    brief: `Two courier marks identify safe job points, with the last parcel delivered to Tern: the Tern Wharf canal parapet and the Kingsland courier arch wall. Legal carrier signage; an optional sealed instruction envelope. The twist: one sign was once used to mark a false drop-off.`,
    openTitle: `Read aloud: Tern marks the drop`,
    open: `Tern hands you a stencil: a tern in flight, wings out, and an arrow underneath. "Safe drop," she says. "Where you see this, a driver can leave a parcel and someone'll collect it within the hour." She hands you an envelope. "And deliver this to me at the Wharf when you're done. Don't open it. Over."`,
    cast: ['mara-boyd', 'yasmin-dale'],
    roles: {'mara-boyd': `Tern. Marking safe drop points for her drivers.`, 'yasmin-dale': `At the Courier Arch. Remembers when a fake sign caused trouble.`},
    scenes: [
      {at: 'SP-LF-KINGSLAND-ARCH', title: `The Kingsland courier arch wall`, read: `The Courier Arch's side wall, beside your old practice tag. Yasmin Dale watches. "There used to be a drop sign here," she says. "Someone faked it last year. Drivers left parcels for a thief for a week." She looks at you. "Make sure yours can't be copied."`,
        text: `The twist: a sign here was once faked. Make it distinctive.`,
        checks: [['sav', 'medium', `Add a detail only real drivers would know to check`, `A tiny number under the arrow: today's dispatch code. Uncopyable.`, `Just the stencil. Copyable.`]]},
      {at: 'SP-HX-TERN', title: `The Tern Wharf canal parapet`, read: `The canal parapet at Tern Wharf. Tern's dispatch room window looks right out over it. She waves from inside.`,
        text: `Legal carrier signage. Then deliver the envelope.`,
        checks: [['grf', 'easy', `Resist the urge to steam open the envelope`, `You don't. (It's a thank-you card and a tenner each.)`, `You peek. Tern knows.`],
          ['aim', 'easy', `Throw the envelope up to Tern's open window`, `Caught. She grins.`, `It lands in the canal. You fish it out.`]]}
    ],
    closeTitle: `Read aloud: safe drop`,
    close: `Tern opens the envelope at her desk: a thank-you card, signed by twelve drivers, and four tenners. "From the drivers," she says. "For the marks." She looks out of the window at the tern on the parapet. "Last year somebody faked a drop sign and a lad lost a week's wages paying back parcels." She puts the card on her desk. "Not this year. Over."`,
    notes: [`Legal carrier signage.`,
      `The sealed instruction envelope is optional cargo.`,
      `Reward: £65. Leads to TG-TU-02.`]
  },
  'tg-tu-02': {
    brief: `Follow a towpath circuit and identify the correct recipient by their tag: the Barge East quayside retaining wall, the Clapton canal footbridge support and the Roman Exchange stall shutter. Mixed legal status across three sites. Sorted or better. The twist: the Night Market claims the Roman Road shutter.`,
    openTitle: `Read aloud: under the bridges`,
    open: `Tern traces a route on a canal map with her finger: Barge East, Clapton, then off the canal to Roman Road. "Three marks," she says. "Each one tells the next driver where the parcel goes. Like a relay." She taps Roman Road. "The last one's on a market stall shutter." She frowns. "Pearl might have something to say about that."`,
    cast: ['mara-boyd', 'indira-shaw', 'pearl-okonkwo'],
    roles: {'mara-boyd': `Tern. Building a relay route.`, 'indira-shaw': `Workshop manager on Barge East. Lets you use the quayside wall.`, 'pearl-okonkwo': `Claims the Roman Road shutter.`},
    scenes: [
      {at: 'SP-VW-BARGE', title: `The Barge East quayside retaining wall`, read: `The quayside at Barge East: the Dutch barge moored on the Lea, fairy lights, a retaining wall at the water's edge. Indira Shaw waves from the deck. "Gloves on, phones away," she says. "And don't fall in."`,
        text: `Permitted.`,
        checks: [['mov', 'medium', `Lean out over the water to paint the retaining wall`, `Steady. Done.`, `You slip. Wet shoe.`]]},
      {at: 'SP-CL-TOWPATH', title: `The Clapton canal footbridge support`, read: `The Clapton footbridge again, now with three of your tags on it. Fourth time lucky.`,
        text: `Unpermitted, but quiet.`,
        checks: [['grt', 'easy', `Paint at 5am before the rowers arrive`, `Done by first light.`, `The rowers arrive. Ezra waves.`]]},
      {at: 'SP-OF-ROMAN', title: `The Roman Exchange stall shutter`, read: `Roman Road market at dawn. Pearl Okonkwo stands in front of the Roman Exchange stall shutter in her market apron, arms folded. Her lantern mark is already on it. "My shutter," she says. "My market." She looks at Tern's stencil in your hand. "You'll need to ask nicely."`,
        text: `The twist: the Night Market claims this shutter.`,
        checks: [['frt', 'medium', `Ask Pearl nicely, and offer her something for it`, `"Everybody eats. Fine. Small one. Under my lantern."`, `"No."`],
          ['whl', 'medium', `Do the whole circuit by van in under an hour, to prove it works`, `Fifty-two minutes.`, `Lost at the Wick. An hour and a half.`]]}
    ],
    closeTitle: `Read aloud: the relay`,
    close: `Tern tests the relay herself: a parcel left under the Barge East mark at noon, collected at Clapton by two, delivered under the Roman Road shutter by four. She stands in front of Pearl's stall with the parcel. Pearl looks at the tern under her lantern, and at Tern. "Under my lantern," Pearl says. "Not over it." Tern nods. "Under it." Pearl hands her a cup of tea.`,
    notes: [`Mixed legal status across three sites. Sorted or better.`,
      `The Night Market claims the Roman Road shutter. Overpainting affects NM stance.`,
      `Reward: £130 and 1 TU Renown. Leads to TG-TU-03.`]
  },
  'tg-tu-03': {
    brief: `Create a visible transport route ending at the rail yard: the Marshgate Delivery Depot outer wall, the Carpenters Road bridge pier and the Temple Mills depot carriage. The player carries an actual delivery docket if the story needs it; the train prop is stationary only. One Smashed It or better. The twist: a rival mover has changed the route during the job.`,
    openTitle: `Read aloud: last van standing`,
    open: `Tern hands you a delivery docket. "Marshgate, Carpenters Road, Temple Mills," she says. "The last route. Paint it so every van in East London knows which way the rail freight goes." She taps the docket. "Carry this. Deliver it to the yard at the end." Her radio crackles. Someone says, "Route's changed, Tern." She frowns. "Who changed it?"`,
    cast: ['mara-boyd', 'gita-mercer'],
    roles: {'mara-boyd': `Tern. Marking the freight route.`, 'gita-mercer': `Stores keeper at Marshgate. Saw the rival mover change the route.`},
    scenes: [
      {at: 'SP-BF-MARSHGATE', title: `The Marshgate Delivery Depot outer wall`, read: `The outer wall of the Marshgate depot. Gita Mercer stands at the gate with her clipboard. "Somebody's put up a new route sign," she says, pointing at a fresh arrow on the wall pointing the wrong way. "Not Tern's. A rival mover."`,
        text: `The twist: a rival mover has changed the route. Paint the correct arrow.`,
        checks: [['sav', 'medium', `Work out where the rival's arrow is sending vans`, `Into a dead-end yard where their own vans can pick up loads first.`, `You can't tell.`],
          ['mus', 'easy', `Drag the rival's sandwich-board sign out of the way`, `Moved.`, `It's chained.`]]},
      {at: 'SP-ST-CARPENTERS', title: `The Carpenters Road bridge pier`, read: `The Carpenters Road pier, again. By now, the fox knows you.`,
        text: `The middle of the route.`,
        checks: [['btl', 'easy', `Keep painting when a van from the rival mover slows down beside you`, `You don't look up. It drives on.`, `You look up. The driver takes a photo of you.`]]},
      {at: 'SP-HM-TEMPLE-TRAIN', title: `The Temple Mills depot carriage`, read: `Temple Mills depot. The out-of-service carriage at the end of the siding. Go for Smashed It here: the end of the route.`,
        text: `Stationary prop only. Deliver the docket here.`,
        checks: [['aim', 'medium', `Get the arrow perfectly level along the side of the carriage`, `Smashed It.`, `It droops. Sorted.`],
          ['whl', 'medium', `Beat the rival's van to the depot gate with the docket`, `First through the gate.`, `They're there first.`]]}
    ],
    closeTitle: `Read aloud: the right way`,
    close: `The next morning, every van coming out of Marshgate follows your arrows: Carpenters Road, Temple Mills, the rail yard. The rival mover's vans sit in their dead-end yard, empty. Tern watches it all from the dispatch room on a screen. "Last van standing," she says. She clicks her radio. "All drivers: follow the tern. Over."`,
    notes: [`The train prop must be stationary.`,
      `The delivery docket is optional cargo if the story needs it.`,
      `One Smashed It or better.`,
      `Reward: £220. Completes the TU tagging line.`]
  }
};
